#define P2D89_CORDIC_K 9949
static const p2d89_u16 p2d89_cordic_atan_turn[15]={8192U,4836U,2555U,1297U,651U,326U,163U,81U,41U,20U,10U,5U,3U,1U,1U};
static int p2d89_emit_raw(const P2D89_Provider *p,unsigned char op,p2d89_q14 x1,p2d89_q14 y1,p2d89_q14 x2,p2d89_q14 y2,p2d89_q14 x3,p2d89_q14 y3){P2D89_Command c;if(p==0||p->emit==0)return 0;c.opcode=op;c.x1=x1;c.y1=y1;c.x2=x2;c.y2=y2;c.x3=x3;c.y3=y3;return p->emit(p->user,&c);} 
int p2d89_i_point(const P2D89_Provider *p,p2d89_q14 x,p2d89_q14 y){return p2d89_emit_raw(p,P2D89_OP_POINT,x,y,0,0,0,0);} 
int p2d89_i_move(const P2D89_Provider *p,p2d89_q14 x,p2d89_q14 y){return p2d89_emit_raw(p,P2D89_OP_MOVE,x,y,0,0,0,0);} 
int p2d89_i_line(const P2D89_Provider *p,p2d89_q14 x,p2d89_q14 y){return p2d89_emit_raw(p,P2D89_OP_LINE,x,y,0,0,0,0);} 
int p2d89_i_quad(const P2D89_Provider *p,p2d89_q14 cx,p2d89_q14 cy,p2d89_q14 x,p2d89_q14 y){return p2d89_emit_raw(p,P2D89_OP_QUAD,cx,cy,x,y,0,0);} 
int p2d89_i_cubic(const P2D89_Provider *p,p2d89_q14 a,p2d89_q14 b,p2d89_q14 c,p2d89_q14 d,p2d89_q14 x,p2d89_q14 y){return p2d89_emit_raw(p,P2D89_OP_CUBIC,a,b,c,d,x,y);} 
int p2d89_i_close(const P2D89_Provider *p){return p2d89_emit_raw(p,P2D89_OP_CLOSE,0,0,0,0,0,0);} 
p2d89_q14 p2d89_mul_q14(p2d89_q14 a,p2d89_q14 b){p2d89_i32 v;v=(p2d89_i32)a*(p2d89_i32)b;if(v>=0)v+=8192;else v-=8192;v>>=14;if(v>32767)v=32767;if(v<-32768)v=-32768;return(p2d89_q14)v;}
void p2d89_sincos_turn(p2d89_u16 turn,p2d89_q14 *os,p2d89_q14 *oc){p2d89_i32 z,x,y,nx,ny,sx,sy;p2d89_u16 local;int i;if(turn<16384U){local=turn;sx=1;sy=1;}else if(turn<32768U){local=(p2d89_u16)(32768U-turn);sx=-1;sy=1;}else if(turn<49152U){local=(p2d89_u16)(turn-32768U);sx=-1;sy=-1;}else{local=(p2d89_u16)(65535U-turn+1U);sx=1;sy=-1;}x=P2D89_CORDIC_K;y=0;z=(p2d89_i32)local;for(i=0;i<15;++i){if(z>=0){nx=x-(y>>i);ny=y+(x>>i);z-=(p2d89_i32)p2d89_cordic_atan_turn[i];}else{nx=x+(y>>i);ny=y-(x>>i);z+=(p2d89_i32)p2d89_cordic_atan_turn[i];}x=nx;y=ny;}x*=sx;y*=sy;if(x>P2D89_ONE)x=P2D89_ONE;if(x<-P2D89_ONE)x=-P2D89_ONE;if(y>P2D89_ONE)y=P2D89_ONE;if(y<-P2D89_ONE)y=-P2D89_ONE;if(os)*os=(p2d89_q14)y;if(oc)*oc=(p2d89_q14)x;}
void p2d89_i_rotate(p2d89_q14 x,p2d89_q14 y,p2d89_u16 turn,p2d89_q14 *ox,p2d89_q14 *oy){p2d89_q14 s,c;p2d89_i32 rx,ry;p2d89_sincos_turn(turn,&s,&c);rx=(p2d89_i32)x*c-(p2d89_i32)y*s;ry=(p2d89_i32)x*s+(p2d89_i32)y*c;if(rx>=0)rx+=8192;else rx-=8192;if(ry>=0)ry+=8192;else ry-=8192;rx>>=14;ry>>=14;if(ox)*ox=(p2d89_q14)rx;if(oy)*oy=(p2d89_q14)ry;}
int p2d89_i_poly(const p2d89_q14 *xy,unsigned int count,int close_path,const P2D89_Provider *p){unsigned int i;if(xy==0||count==0U)return 0;if(!p2d89_i_move(p,xy[0],xy[1]))return 0;for(i=1U;i<count;++i)if(!p2d89_i_line(p,xy[i*2U],xy[i*2U+1U]))return 0;if(close_path&&!p2d89_i_close(p))return 0;return 1;}
int p2d89_i_rot_poly(const p2d89_q14 *xy,unsigned int count,p2d89_u16 turn,int close_path,const P2D89_Provider *p){unsigned int i;p2d89_q14 x,y;if(xy==0||count==0U)return 0;p2d89_i_rotate(xy[0],xy[1],turn,&x,&y);if(!p2d89_i_move(p,x,y))return 0;for(i=1U;i<count;++i){p2d89_i_rotate(xy[i*2U],xy[i*2U+1U],turn,&x,&y);if(!p2d89_i_line(p,x,y))return 0;}if(close_path&&!p2d89_i_close(p))return 0;return 1;}
int p2d89_emit_regular_polygon(unsigned int sides,p2d89_u16 rot,const P2D89_Provider *p){unsigned int i;p2d89_u32 phase,step;p2d89_q14 s,c;if(p==0||p->emit==0||sides<3U||sides>P2D89_DEFAULT_MAX_SIDES)return 0;step=65536U/sides;phase=(p2d89_u32)rot;p2d89_sincos_turn((p2d89_u16)phase,&s,&c);if(!p2d89_i_move(p,c,s))return 0;for(i=1U;i<sides;++i){phase=(p2d89_u32)rot+step*i;p2d89_sincos_turn((p2d89_u16)(phase&65535U),&s,&c);if(!p2d89_i_line(p,c,s))return 0;}return p2d89_i_close(p);}
int p2d89_emit_star(unsigned int points,p2d89_q14 inner,p2d89_u16 rot,const P2D89_Provider *p){unsigned int i,vc;p2d89_u32 phase,step;p2d89_q14 s,c,x,y,r;if(p==0||p->emit==0||points<2U||points>P2D89_DEFAULT_MAX_STAR_POINTS||inner<=0||inner>=P2D89_ONE)return 0;vc=points*2U;step=65536U/vc;for(i=0U;i<vc;++i){phase=(p2d89_u32)rot+step*i;p2d89_sincos_turn((p2d89_u16)(phase&65535U),&s,&c);r=((i&1U)==0U)?(p2d89_q14)P2D89_ONE:inner;x=p2d89_mul_q14(c,r);y=p2d89_mul_q14(s,r);if(i==0U){if(!p2d89_i_move(p,x,y))return 0;}else if(!p2d89_i_line(p,x,y))return 0;}return p2d89_i_close(p);}
int p2d89_emit_ellipse(p2d89_q14 rx,p2d89_q14 ry,int cw,const P2D89_Provider *p){p2d89_q14 kx,ky;if(p==0||p->emit==0||rx<=0||ry<=0)return 0;kx=p2d89_mul_q14(rx,P2D89_KAPPA);ky=p2d89_mul_q14(ry,P2D89_KAPPA);if(cw){if(!p2d89_i_move(p,rx,0))return 0;if(!p2d89_i_cubic(p,rx,ky,kx,ry,0,ry))return 0;if(!p2d89_i_cubic(p,(p2d89_q14)-kx,ry,(p2d89_q14)-rx,ky,(p2d89_q14)-rx,0))return 0;if(!p2d89_i_cubic(p,(p2d89_q14)-rx,(p2d89_q14)-ky,(p2d89_q14)-kx,(p2d89_q14)-ry,0,(p2d89_q14)-ry))return 0;if(!p2d89_i_cubic(p,kx,(p2d89_q14)-ry,rx,(p2d89_q14)-ky,rx,0))return 0;}else{if(!p2d89_i_move(p,rx,0))return 0;if(!p2d89_i_cubic(p,rx,(p2d89_q14)-ky,kx,(p2d89_q14)-ry,0,(p2d89_q14)-ry))return 0;if(!p2d89_i_cubic(p,(p2d89_q14)-kx,(p2d89_q14)-ry,(p2d89_q14)-rx,(p2d89_q14)-ky,(p2d89_q14)-rx,0))return 0;if(!p2d89_i_cubic(p,(p2d89_q14)-rx,ky,(p2d89_q14)-kx,ry,0,ry))return 0;if(!p2d89_i_cubic(p,kx,ry,rx,ky,rx,0))return 0;}return p2d89_i_close(p);}
int p2d89_i_rounded_rect(p2d89_q14 hx,p2d89_q14 hy,p2d89_q14 r,const P2D89_Provider *p){p2d89_q14 kr,x0,y0;if(r<=0||r>hx||r>hy)return 0;kr=p2d89_mul_q14(r,P2D89_KAPPA);x0=(p2d89_q14)(hx-r);y0=(p2d89_q14)(hy-r);if(!p2d89_i_move(p,x0,(p2d89_q14)-hy))return 0;if(!p2d89_i_line(p,(p2d89_q14)-x0,(p2d89_q14)-hy))return 0;if(!p2d89_i_cubic(p,(p2d89_q14)(-x0-kr),(p2d89_q14)-hy,(p2d89_q14)-hx,(p2d89_q14)(-y0-kr),(p2d89_q14)-hx,(p2d89_q14)-y0))return 0;if(!p2d89_i_line(p,(p2d89_q14)-hx,y0))return 0;if(!p2d89_i_cubic(p,(p2d89_q14)-hx,(p2d89_q14)(y0+kr),(p2d89_q14)(-x0-kr),hy,(p2d89_q14)-x0,hy))return 0;if(!p2d89_i_line(p,x0,hy))return 0;if(!p2d89_i_cubic(p,(p2d89_q14)(x0+kr),hy,hx,(p2d89_q14)(y0+kr),hx,y0))return 0;if(!p2d89_i_line(p,hx,(p2d89_q14)-y0))return 0;if(!p2d89_i_cubic(p,hx,(p2d89_q14)(-y0-kr),(p2d89_q14)(x0+kr),(p2d89_q14)-hy,x0,(p2d89_q14)-hy))return 0;return p2d89_i_close(p);}
int p2d89_i_frame(p2d89_q14 hx,p2d89_q14 hy,p2d89_q14 inset,const P2D89_Provider *p){p2d89_q14 o[8],i[8],ix,iy;ix=(p2d89_q14)(hx-inset);iy=(p2d89_q14)(hy-inset);if(ix<=0||iy<=0)return 0;o[0]=(p2d89_q14)-hx;o[1]=(p2d89_q14)-hy;o[2]=hx;o[3]=(p2d89_q14)-hy;o[4]=hx;o[5]=hy;o[6]=(p2d89_q14)-hx;o[7]=hy;i[0]=(p2d89_q14)-ix;i[1]=(p2d89_q14)-iy;i[2]=(p2d89_q14)-ix;i[3]=iy;i[4]=ix;i[5]=iy;i[6]=ix;i[7]=(p2d89_q14)-iy;if(!p2d89_i_poly(o,4U,1,p))return 0;return p2d89_i_poly(i,4U,1,p);}
int p2d89_i_semicircle(int filled,const P2D89_Provider *p){p2d89_q14 k;k=P2D89_KAPPA;if(!p2d89_i_move(p,(p2d89_q14)-P2D89_ONE,0))return 0;if(!p2d89_i_cubic(p,(p2d89_q14)-P2D89_ONE,(p2d89_q14)-k,(p2d89_q14)-k,(p2d89_q14)-P2D89_ONE,0,(p2d89_q14)-P2D89_ONE))return 0;if(!p2d89_i_cubic(p,k,(p2d89_q14)-P2D89_ONE,P2D89_ONE,(p2d89_q14)-k,P2D89_ONE,0))return 0;if(filled){if(!p2d89_i_line(p,(p2d89_q14)-P2D89_ONE,0))return 0;return p2d89_i_close(p);}return 1;}
int p2d89_i_quarter_circle(int filled,const P2D89_Provider *p){if(!p2d89_i_move(p,0,0))return 0;if(filled){if(!p2d89_i_line(p,P2D89_ONE,0))return 0;}else if(!p2d89_i_move(p,P2D89_ONE,0))return 0;if(!p2d89_i_cubic(p,P2D89_ONE,P2D89_KAPPA,P2D89_KAPPA,P2D89_ONE,0,P2D89_ONE))return 0;if(filled){if(!p2d89_i_line(p,0,0))return 0;return p2d89_i_close(p);}return 1;}
int p2d89_i_lens(p2d89_q14 bend,const P2D89_Provider *p){if(!p2d89_i_move(p,(p2d89_q14)-P2D89_ONE,0))return 0;if(!p2d89_i_cubic(p,(p2d89_q14)-P2D89_HALF,(p2d89_q14)-bend,P2D89_HALF,(p2d89_q14)-bend,P2D89_ONE,0))return 0;if(!p2d89_i_cubic(p,P2D89_HALF,bend,(p2d89_q14)-P2D89_HALF,bend,(p2d89_q14)-P2D89_ONE,0))return 0;return p2d89_i_close(p);}
int p2d89_i_arc_3q(const P2D89_Provider *p){if(!p2d89_i_move(p,P2D89_ONE,0))return 0;if(!p2d89_i_cubic(p,P2D89_ONE,P2D89_KAPPA,P2D89_KAPPA,P2D89_ONE,0,P2D89_ONE))return 0;if(!p2d89_i_cubic(p,(p2d89_q14)-P2D89_KAPPA,P2D89_ONE,(p2d89_q14)-P2D89_ONE,P2D89_KAPPA,(p2d89_q14)-P2D89_ONE,0))return 0;return p2d89_i_cubic(p,(p2d89_q14)-P2D89_ONE,(p2d89_q14)-P2D89_KAPPA,(p2d89_q14)-P2D89_KAPPA,(p2d89_q14)-P2D89_ONE,0,(p2d89_q14)-P2D89_ONE);}
int p2d89_emit_spiral(unsigned int turns_q8,unsigned int segments,const P2D89_Provider *p){unsigned int i;p2d89_u32 total_turn,phase;p2d89_q14 s,c,r,x,y;if(p==0||p->emit==0||segments<4U||segments>256U||turns_q8==0U||turns_q8>2048U)return 0;total_turn=(p2d89_u32)turns_q8*256U;for(i=0U;i<=segments;++i){phase=(total_turn*i)/segments;r=(p2d89_q14)(((p2d89_u32)P2D89_ONE*i)/segments);p2d89_sincos_turn((p2d89_u16)(phase&65535U),&s,&c);x=p2d89_mul_q14(c,r);y=p2d89_mul_q14(s,r);if(i==0U){if(!p2d89_i_move(p,x,y))return 0;}else if(!p2d89_i_line(p,x,y))return 0;}return 1;}

int p2d89_emit_star_polygon(unsigned int vertices,unsigned int step,p2d89_u16 rot,const P2D89_Provider *p){unsigned int i,index;p2d89_u32 phase,unit;p2d89_q14 sn,cs;if(p==0||p->emit==0||vertices<3U||vertices>P2D89_DEFAULT_MAX_SIDES||step<2U||step>=vertices)return 0;unit=65536U/vertices;index=0U;for(i=0U;i<vertices;++i){phase=(p2d89_u32)rot+unit*index;p2d89_sincos_turn((p2d89_u16)(phase&65535U),&sn,&cs);if(i==0U){if(!p2d89_i_move(p,cs,sn))return 0;}else if(!p2d89_i_line(p,cs,sn))return 0;index=(index+step)%vertices;}return p2d89_i_close(p);}
